import WebSocket from 'ws';
import { createServer, IncomingMessage } from 'http';
import { randomBytes, createHmac, timingSafeEqual } from 'crypto';

interface ConnectionPool {
  connections: Map<string, WebSocket>;
  tokens: Map<string, { userId: string; expires: number; nonce: string }>;
}

interface EmailRequest {
  to: string;
  subject: string;
  body: string;
  priority?: 'high' | 'normal' | 'low';
}

const SECRET = process.env.HMAC_SECRET || randomBytes(32).toString('hex');
const TOKEN_ISSUER_API_KEY = process.env.TOKEN_ISSUER_API_KEY || '';
const pool: ConnectionPool = {
  connections: new Map(),
  tokens: new Map(),
};

function generateToken(userId: string): string {
  const nonce = randomBytes(16).toString('hex');
  const payload = `${userId}:${nonce}:${Date.now()}`;
  const hmac = createHmac('sha256', SECRET).update(payload).digest('hex');
  const token = Buffer.from(`${payload}:${hmac}`).toString('base64');
  pool.tokens.set(token, { userId, expires: Date.now() + 300000, nonce });
  return token;
}

function validateToken(token: string): { valid: boolean; userId?: string } {
  const entry = pool.tokens.get(token);
  if (!entry) return { valid: false };
  if (Date.now() > entry.expires) {
    pool.tokens.delete(token);
    return { valid: false };
  }
  try {
    const decoded = Buffer.from(token, 'base64').toString('utf-8');
    const parts = decoded.split(':');
    if (parts.length !== 4) return { valid: false };
    const [userId, nonce, timestamp, providedHmac] = parts;
    const expectedPayload = `${userId}:${nonce}:${timestamp}`;
    const expectedHmac = createHmac('sha256', SECRET).update(expectedPayload).digest('hex');
    const providedBuf = Buffer.from(providedHmac, 'utf-8');
    const expectedBuf = Buffer.from(expectedHmac, 'utf-8');
    if (providedBuf.length !== expectedBuf.length) return { valid: false };
    if (!timingSafeEqual(providedBuf, expectedBuf)) return { valid: false };
    return { valid: true, userId };
  } catch {
    return { valid: false };
  }
}

function extractOrigin(req: IncomingMessage): string {
  return req.headers['origin'] || '';
}

function isAllowedOrigin(origin: string): boolean {
  const allowed = ['https://mail.example.com', 'https://admin.example.com'];
  return allowed.includes(origin);
}

function authenticateUpgrade(req: IncomingMessage): { authenticated: boolean; userId?: string } {
  const url = new URL(req.url || '/', `http://${req.headers.host}`);
  const token = url.searchParams.get('token');
  if (!token) return { authenticated: false };
  const result = validateToken(token);
  return { authenticated: result.valid, userId: result.userId };
}

function handleConnection(ws: WebSocket, req: IncomingMessage, userId: string): void {
  const connectionId = randomBytes(8).toString('hex');
  pool.connections.set(connectionId, ws);

  ws.on('message', (data: WebSocket.Data) => {
    try {
      const message = JSON.parse(data.toString());
      if (message.type === 'send_email') {
        processEmailRequest(message.payload as EmailRequest, userId, ws);
      } else if (message.type === 'pool_status') {
        ws.send(JSON.stringify({ type: 'status', active: pool.connections.size }));
      }
    } catch (e) {
      ws.send(JSON.stringify({ type: 'error', message: 'Invalid message format' }));
    }
  });

  ws.on('close', () => {
    pool.connections.delete(connectionId);
  });
}

function processEmailRequest(email: EmailRequest, userId: string, ws: WebSocket): void {
  if (!email.to || !email.subject || !email.body) {
    ws.send(JSON.stringify({ type: 'error', message: 'Missing required fields' }));
    return;
  }
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(email.to)) {
    ws.send(JSON.stringify({ type: 'error', message: 'Invalid email address' }));
    return;
  }
  ws.send(JSON.stringify({ type: 'sent', to: email.to, from: `${userId}@example.com` }));
}

function isAuthorizedIssuer(req: IncomingMessage): boolean {
  if (!TOKEN_ISSUER_API_KEY) return false;
  const provided = req.headers['x-api-key'];
  const providedKey = Array.isArray(provided) ? provided[0] : provided;
  if (!providedKey) return false;
  const providedBuf = Buffer.from(providedKey, 'utf-8');
  const expectedBuf = Buffer.from(TOKEN_ISSUER_API_KEY, 'utf-8');
  if (providedBuf.length !== expectedBuf.length) return false;
  return timingSafeEqual(providedBuf, expectedBuf);
}

const server = createServer((req, res) => {
  if (req.url?.startsWith('/api/token') && req.method === 'POST') {
    if (!isAuthorizedIssuer(req)) {
      res.writeHead(401);
      res.end('Unauthorized');
      return;
    }
    let body = '';
    req.on('data', chunk => body += chunk);
    req.on('end', () => {
      try {
        const { userId } = JSON.parse(body);
        if (typeof userId !== 'string' || !/^[A-Za-z0-9_-]{1,64}$/.test(userId)) {
          res.writeHead(400);
          res.end('Invalid userId');
          return;
        }
        const token = generateToken(userId);
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ token }));
      } catch {
        res.writeHead(400);
        res.end('Bad request');
      }
    });
  } else {
    res.writeHead(404);
    res.end('Not found');
  }
});

const wss = new WebSocket.Server({ noServer: true });

server.on('upgrade', (req: IncomingMessage, socket, head) => {
  const origin = extractOrigin(req);
  const { authenticated, userId } = authenticateUpgrade(req);

  if (!authenticated || !userId) {
    socket.write('HTTP/1.1 401 Unauthorized\r\n\r\n');
    socket.destroy();
    return;
  }

  if (isAllowedOrigin(origin)) {
    wss.handleUpgrade(req, socket, head, (ws) => {
      handleConnection(ws, req, userId);
    });
  } else {
    socket.write('HTTP/1.1 403 Forbidden\r\n\r\n');
    socket.destroy();
  }
});

server.listen(8080, () => console.log('Email WS service on :8080'));
